from pyscipopt import Model, quicksum
import json

# Data
workers = ['I', 'II', 'III', 'IV', 'V']
tasks = ['A', 'B', 'C', 'D']
hours = {
    'I':   [9, 4, 3, 7],
    'II':  [4, 6, 5, 6],
    'III': [5, 4, 7, 5],
    'IV':  [7, 5, 2, 3],
    'V':   [10, 6, 7, 4],
}

m = Model("worker_assignment")
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables: x[i][j] = 1 if worker i is assigned to task j
x = {}
for i in workers:
    for j in tasks:
        x[i, j] = m.addVar(name=f"x_{i}_{j}", vtype="B", lb=0, ub=1)

# Constraint 1: Each task is assigned exactly one worker
for j in tasks:
    m.addCons(quicksum(x[i, j] for i in workers) == 1, name=f"task_{j}")

# Constraint 2: Each worker is assigned to at most one task
for i in workers:
    m.addCons(quicksum(x[i, j] for j in tasks) <= 1, name=f"worker_{i}")

# Objective: Minimize total working hours
m.setObjective(
    quicksum(hours[i][j_idx] * x[i, j] for i in workers for j_idx, j in enumerate(tasks)),
    "minimize"
)

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
    for i in workers:
        for j in tasks:
            if m.getVal(x[i, j]) > 0.5:
                print(f"Worker {i} -> Task {j} ({hours[i][tasks.index(j)]} hours)")

