from pyscipopt import Model, quicksum
import json

# Data
# Processing time per piece (hours)
# Equipment: A1, A2, B1, B2, B3
# Products: I, II, III
proc_time = {
    ('A1', 'I'): 5, ('A1', 'II'): 10, ('A1', 'III'): None,
    ('A2', 'I'): 7, ('A2', 'II'): 9,  ('A2', 'III'): 12,
    ('B1', 'I'): 6, ('B1', 'II'): 8,  ('B1', 'III'): None,
    ('B2', 'I'): 4, ('B2', 'II'): None, ('B2', 'III'): 11,
    ('B3', 'I'): 7, ('B3', 'II'): None, ('B3', 'III'): None,
}

# Effective machine hours
avail = {'A1': 6000, 'A2': 10000, 'B1': 4000, 'B2': 7000, 'B3': 4000}

# Processing cost per machine hour (Yuan/hour)
cost_hour = {'A1': 0.05, 'A2': 0.03, 'B1': 0.06, 'B2': 0.11, 'B3': 0.05}

# Raw material cost per piece
raw_cost = {'I': 0.25, 'II': 0.35, 'III': 0.5}

# Unit price (revenue per piece)
price = {'I': 1.25, 'II': 2.0, 'III': 2.8}

# Products and equipment
products = ['I', 'II', 'III']
stageA = ['A1', 'A2']
stageB = ['B1', 'B2', 'B3']

# Which equipment can process which product
# Product I: A1, A2, B1, B2, B3
# Product II: A1, A2, B1
# Product III: A2, B2
valid_A = {'I': ['A1', 'A2'], 'II': ['A1', 'A2'], 'III': ['A2']}
valid_B = {'I': ['B1', 'B2', 'B3'], 'II': ['B1'], 'III': ['B2']}

# Create model
m = Model("FactoryProduction")
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables: x[e][p] = number of pieces of product p processed on equipment e
x = {}
for e in stageA + stageB:
    for p in products:
        if (e in valid_A[p]) or (e in valid_B[p]):
            x[(e, p)] = m.addVar(name=f"x_{e}_{p}", lb=0.0, vtype="C")

# Balance constraints: total on stage A = total on stage B for each product
for p in products:
    lhs_A = quicksum(x[(e, p)] for e in stageA if (e, p) in x)
    lhs_B = quicksum(x[(e, p)] for e in stageB if (e, p) in x)
    m.addCons(lhs_A == lhs_B, name=f"balance_{p}")

# Machine availability constraints
for e in stageA + stageB:
    terms = [proc_time[(e, p)] * x[(e, p)] for p in products if (e, p) in x]
    if terms:
        m.addCons(quicksum(terms) <= avail[e], name=f"avail_{e}")

# Objective: maximize profit
# Profit = sum over products of (price - raw_cost) * total_produced
#         - sum over (e,p) of proc_time * cost_hour * x
# total_produced for product p = sum of x on stage A (or B, they're equal)
obj_terms = []
for p in products:
    total_prod = quicksum(x[(e, p)] for e in stageA if (e, p) in x)
    obj_terms.append((price[p] - raw_cost[p]) * total_prod)

for e in stageA + stageB:
    for p in products:
        if (e, p) in x:
            obj_terms.append(-proc_time[(e, p)] * cost_hour[e] * x[(e, p)])

m.setObjective(quicksum(obj_terms), "maximize")

# Solve
m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
    for e in stageA + stageB:
        for p in products:
            if (e, p) in x:
                val = m.getVal(x[(e, p)])
                if val > 1e-6:
                    print(f"  x[{e}][{p}] = {val:.4f}")

