from pyscipopt import Model, quicksum
import json

# Data: processing times p[i][j] = time for batch i on vat j
p = [
    [3, 1, 1],
    [2, 1.5, 1],
    [3, 1.2, 1.3],
    [2, 2, 2],
    [2.1, 2, 3]
]

n = 5  # number of batches (jobs)
m = 3  # number of vats (machines)
M = 30  # big-M upper bound

m_model = Model()
m_model.hideOutput()
m_model.setRealParam("limits/time", 570)

# Decision variables
# z[i][j] = 1 if batch i is scheduled before batch j (permutation flow shop)
z = {}
for i in range(n):
    for j in range(n):
        if i != j:
            z[i, j] = m_model.addVar(vtype="B", name=f"z_{i}_{j}")

# C[i][j] = completion time of batch i on vat j
C = {}
for i in range(n):
    for j in range(m):
        C[i, j] = m_model.addVar(vtype="C", lb=0, name=f"C_{i}_{j}")

# Cmax = makespan
Cmax = m_model.addVar(vtype="C", lb=0, name="Cmax")

# Constraint 1: z[i][j] + z[j][i] = 1 for all i < j
for i in range(n):
    for j in range(i + 1, n):
        m_model.addCons(z[i, j] + z[j, i] == 1, name=f"seq_{i}_{j}")

# Constraint 2: C[i][0] >= p[i][0] (first vat, start at time 0)
for i in range(n):
    m_model.addCons(C[i, 0] >= p[i][0], name=f"start_{i}")

# Constraint 3: C[i][j] >= C[i][j-1] + p[i][j] (flow: must finish previous vat)
for i in range(n):
    for j in range(1, m):
        m_model.addCons(C[i, j] >= C[i, j - 1] + p[i][j], name=f"flow_{i}_{j}")

# Constraint 4: Machine non-overlap (permutation)
# If i before j on machine j: C[i][j] + p[j][j] <= C[j][j]
# Expressed: C[i][j] + p[j][j] - C[j][j] <= M*(1 - z[i][j])
for i in range(n):
    for j in range(n):
        if i != j:
            for k in range(m):
                m_model.addCons(
                    C[i, k] + p[j][k] - C[j, k] <= M * (1 - z[i, j]),
                    name=f"nonoverlap_{i}_{j}_{k}"
                )

# Constraint 5: Cmax >= C[i][m-1] for all i (makespan)
for i in range(n):
    m_model.addCons(Cmax >= C[i, m - 1], name=f"makespan_{i}")

# Objective: minimize makespan
m_model.setObjective(Cmax, "minimize")

m_model.optimize()

st = m_model.getStatus()
print(f"status: {st}")
if m_model.getNSols() > 0:
    print(f"objective: {m_model.getObjVal()}")

