from pyscipopt import Model, quicksum
import json

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Data
students = [1, 2, 3, 4, 5, 6]
day_idx = list(range(5))  # 0=Mon, 1=Tue, 2=Wed, 3=Thu, 4=Fri

wage = {1: 10.0, 2: 10.0, 3: 9.9, 4: 9.8, 5: 10.8, 6: 11.3}

max_hours = {
    1: [6, 0, 6, 0, 7],
    2: [0, 8, 9, 6, 0],
    3: [4, 8, 3, 0, 5],
    4: [5, 5, 6, 0, 4],
    5: [3, 0, 5, 8, 0],
    6: [0, 6, 0, 6, 5],
}

min_hours = {1: 8, 2: 8, 3: 8, 4: 8, 5: 7, 6: 7}

total_hours_per_day = 14
max_shifts_per_student = 2
max_students_per_day = 3

# Decision variables
x = {}
for i in students:
    for d in day_idx:
        x[i, d] = m.addVar(vtype="C", lb=0, ub=max_hours[i][d], name=f"x_{i}_{d}")

y = {}
for i in students:
    for d in day_idx:
        y[i, d] = m.addVar(vtype="B", name=f"y_{i}_{d}")

# Constraints

# 1. Coverage: exactly 14 hours per day (one student on duty at all times)
for d in day_idx:
    m.addCons(quicksum(x[i, d] for i in students) == total_hours_per_day, name=f"coverage_{d}")

# 2. Link: x[i,d] <= max_hours[i,d] * y[i,d]
for i in students:
    for d in day_idx:
        if max_hours[i][d] > 0:
            m.addCons(x[i, d] <= max_hours[i][d] * y[i, d], name=f"link_{i}_{d}")
        else:
            m.addCons(x[i, d] == 0, name=f"link_{i}_{d}")

# 3. Minimum weekly hours per student
for i in students:
    m.addCons(quicksum(x[i, d] for d in day_idx) >= min_hours[i], name=f"min_hours_{i}")

# 4. At most 2 shifts (days) per student per week
for i in students:
    m.addCons(quicksum(y[i, d] for d in day_idx) <= max_shifts_per_student, name=f"max_shifts_{i}")

# 5. At most 3 students scheduled per day
for d in day_idx:
    m.addCons(quicksum(y[i, d] for i in students) <= max_students_per_day, name=f"max_students_{d}")

# Objective: minimize total gross pay
obj = quicksum(wage[i] * x[i, d] for i in students for d in day_idx)
m.setObjective(obj, "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

