from pyscipopt import Model, quicksum
import json

# Data
brands = ['A', 'B', 'C']
materials = ['A', 'B', 'C']
n_b = len(brands)
n_m = len(materials)

raw_cost = {'A': 2.00, 'B': 1.50, 'C': 1.00}
monthly_limit = {'A': 2000, 'B': 2500, 'C': 1200}
proc_fee = {'A': 0.50, 'B': 0.40, 'C': 0.30}
sell_price = {'A': 3.40, 'B': 2.85, 'C': 2.25}

# Content constraints: (brand, material, type, pct)
# type: 'ge' means >=, 'le' means <=
content_constraints = [
    ('A', 'A', 'ge', 0.60),
    ('A', 'C', 'le', 0.20),
    ('B', 'A', 'ge', 0.15),
    ('B', 'C', 'le', 0.60),
    ('C', 'C', 'le', 0.50),
]

# Decision variables: x[i][j] = kg of material j used in brand i
m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

x = {}
for i in brands:
    for j in materials:
        x[i][j] = m.addVar(vtype="C", lb=0.0, name=f"x_{i}_{j}")

# Total production of each brand
X = {}
for i in brands:
    X[i] = quicksum(x[i][j] for j in materials)

# Objective: maximize profit = sum (sell_price[i] - proc_fee[i] - raw_cost[j]) * x[i][j]
obj_terms = []
for i in brands:
    for j in materials:
        coeff = sell_price[i] - proc_fee[i] - raw_cost[j]
        obj_terms.append(coeff * x[i][j])
m.setObjective(quicksum(obj_terms), "maximize")

# Content constraints (linearized)
for (br, mat, ctype, pct) in content_constraints:
    total = quicksum(x[br][j] for j in materials)
    if ctype == 'ge':
        # x[br][mat] >= pct * total  =>  x[br][mat] - pct*total >= 0
        m.addCons(x[br][mat] - pct * total >= 0, name=f"content_{br}_{mat}_ge")
    else:
        # x[br][mat] <= pct * total  =>  x[br][mat] - pct*total <= 0
        m.addCons(x[br][mat] - pct * total <= 0, name=f"content_{br}_{mat}_le")

# Monthly material limits
for j in materials:
    m.addCons(quicksum(x[i][j] for i in brands) <= monthly_limit[j], name=f"limit_{j}")

# Solve
m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
    for i in brands:
        total_i = sum(m.getVal(x[i][j]) for j in materials)
        detail = {j: m.getVal(x[i][j]) for j in materials}
        print(f"Brand {i}: total={total_i:.4f} kg, breakdown={detail}")

